import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"Seitenlayout","description":"Darstellung einer Seite im Portal — Breite, Cover, Farben und Navigation.","frontmatter":{"title":"Seitenlayout","description":"Darstellung einer Seite im Portal — Breite, Cover, Farben und Navigation."},"headers":[],"relativePath":"seiten/seitenlayout.md","filePath":"seiten/seitenlayout.md","lastUpdated":1786088384000}'),r={name:"seiten/seitenlayout.md"};function s(l,e,o,d,h,u){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="seitenlayout" tabindex="-1">Seitenlayout <a class="header-anchor" href="#seitenlayout" aria-label="Permalink to &quot;Seitenlayout&quot;">​</a></h1><p>Die Seiteneinstellungen bestimmen, wie eine Seite als <a href="/seiten/portal-veroeffentlichen">Portal</a> aussieht. Sie erreichen sie über das Seitenmenü (<em>Seitenmenü öffnen</em>).</p><div class="warning custom-block"><p class="custom-block-title">Die Einstellungen wirken im Portal, nicht im Editor</p><p>Am Seitenlayout steht der Hinweis <em>Gilt für die Anzeige im Portal</em>. Im Editor sehen Sie weiterhin die Bearbeitungsansicht.</p><p>Prüfen Sie das Ergebnis über <strong>Vorschau</strong> — wahlweise als <em>Smartphone</em> oder <em>Desktop</em>.</p></div><h2 id="seitenlayout-festlegen" tabindex="-1">Seitenlayout festlegen <a class="header-anchor" href="#seitenlayout-festlegen" aria-label="Permalink to &quot;Seitenlayout festlegen&quot;">​</a></h2><p>Drei Möglichkeiten:</p><table tabindex="0"><thead><tr><th>Layout</th><th>Darstellung</th></tr></thead><tbody><tr><td><strong>Zentrierte Seite</strong></td><td>Inhalt in begrenzter Breite, mittig</td></tr><tr><td><strong>Volle Breite</strong></td><td>Inhalt nutzt die gesamte Fensterbreite</td></tr><tr><td><strong>Kartenansicht</strong></td><td>Inhalt als abgesetzte Karte</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Welches wofür</p><ul><li><strong>Zentrierte Seite</strong> für Textlastiges — Dokumentation, Handbücher, Erklärseiten. Begrenzte Zeilenlänge liest sich besser.</li><li><strong>Volle Breite</strong> für Dashboards und eingebettete Tabellen. Eine <a href="/seiten/auswertungen">Grid-Ansicht</a> braucht Platz.</li><li><strong>Kartenansicht</strong> für kurze, in sich geschlossene Seiten — Anmeldungen, Rückmeldungen, einzelne Formulare.</li></ul></div><h2 id="aussehen" tabindex="-1">Aussehen <a class="header-anchor" href="#aussehen" aria-label="Permalink to &quot;Aussehen&quot;">​</a></h2><p>Im Abschnitt <strong>Seite</strong>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Icon &amp; Farbe festlegen</strong></td><td>Symbol und Farbe in der Navigation</td></tr><tr><td><strong>Cover-Bild hinzufügen</strong></td><td>Bild über dem Seiteninhalt</td></tr><tr><td><strong>Hintergrundfarbe festlegen</strong></td><td>Hintergrund der Seite</td></tr></tbody></table><p>Ist bereits ein Cover gesetzt, heißt die Aktion <strong>Cover-Bild bearbeiten</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Cover-Bild mit Bedacht</p><p>Ein Cover-Bild schiebt den eigentlichen Inhalt nach unten. Auf Mobilgeräten kann das bedeuten, dass Besucher zuerst scrollen müssen, bevor sie etwas Nützliches sehen.</p><p>Für Portale mit einer klaren Aufgabe — Formular ausfüllen, Status ansehen — ist weniger oft mehr.</p></div><h2 id="navigation-einklappbar" tabindex="-1">Navigation einklappbar <a class="header-anchor" href="#navigation-einklappbar" aria-label="Permalink to &quot;Navigation einklappbar&quot;">​</a></h2><p>Bei Seiten mit <strong>Unterseiten</strong> steuert <strong>Navigation einklappbar</strong>, ob Besucher die Navigation zusammenklappen können.</p><div class="tip custom-block"><p class="custom-block-title">Bei vielen Unterseiten einschalten</p><p>Auf schmalen Bildschirmen nimmt eine ausgeklappte Navigation den halben Platz ein. Einklappbar zu sein macht das Portal dort deutlich benutzbarer.</p></div><h2 id="bearbeitung-und-zugriff" tabindex="-1">Bearbeitung und Zugriff <a class="header-anchor" href="#bearbeitung-und-zugriff" aria-label="Permalink to &quot;Bearbeitung und Zugriff&quot;">​</a></h2><p>Im Abschnitt <strong>Bearbeitung &amp; Zugriff</strong>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Seite sperren</strong></td><td><em>Blocks sind nicht mehr bearbeitbar</em></td></tr><tr><td><strong>Richtiges Konto bestätigen</strong></td><td><em>Nutzer bestätigen vor dem Fortfahren ihre Identität.</em></td></tr><tr><td><strong>Beim Laden automatisch absenden</strong></td><td><em>Sendet diese Seite automatisch beim Laden ab.</em></td></tr></tbody></table><h3 id="seite-sperren" tabindex="-1">Seite sperren <a class="header-anchor" href="#seite-sperren" aria-label="Permalink to &quot;Seite sperren&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Für produktive Seiten empfehlenswert</p><p>Sobald eine Seite im Einsatz ist, verhindert die Sperre, dass jemand beim Betrachten versehentlich einen Block verschiebt oder Text überschreibt. Sie lässt sich jederzeit wieder aufheben.</p></div><h3 id="richtiges-konto-bestatigen" tabindex="-1">Richtiges Konto bestätigen <a class="header-anchor" href="#richtiges-konto-bestatigen" aria-label="Permalink to &quot;Richtiges Konto bestätigen&quot;">​</a></h3><p>Zeigt einen Hinweis, mit welchem Konto die Person angemeldet ist, samt Möglichkeit zu bestätigen oder zu wechseln.</p><div class="tip custom-block"><p class="custom-block-title">An geteilten Geräten</p><p>Sinnvoll überall dort, wo mehrere Personen dasselbe Gerät nutzen — Werkstatt, Empfang, Schulungsraum. Verhindert, dass jemand unter fremdem Namen absendet.</p></div><h3 id="beim-laden-automatisch-absenden" tabindex="-1">Beim Laden automatisch absenden <a class="header-anchor" href="#beim-laden-automatisch-absenden" aria-label="Permalink to &quot;Beim Laden automatisch absenden&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Braucht vollständig vorbelegte Werte</p><p>Sendet sich die Seite beim Laden selbst ab, hat niemand Gelegenheit, Felder zu füllen. Alle nötigen Werte müssen über den Link gesetzt sein.</p><p>Der typische Einsatz ist ein QR-Code, dessen Scan unmittelbar einen <a href="/flows/was-ist-ein-flow">Flow</a> startet — etwa eine Anwesenheitsmeldung oder ein Materialabruf.</p></div><h2 id="verwendung-in-flows" tabindex="-1">Verwendung in Flows <a class="header-anchor" href="#verwendung-in-flows" aria-label="Permalink to &quot;Verwendung in Flows&quot;">​</a></h2><p>Der Abschnitt <strong>Verwendung in Flows</strong> zeigt, welche Flows diese Seite anzeigen.</p><div class="warning custom-block"><p class="custom-block-title">Vor dem Löschen prüfen</p><p>Wird die Seite von einem Flow-Schritt verwendet, läuft dieser danach in den Fehler <em>Für diesen Schritt ist keine eigene UI hinterlegt</em>.</p><p>→ <a href="/flows/seiten-in-flows">Seiten in Flows</a></p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></li><li><a href="/seiten/portal-einbetten">Portal einbetten</a></li><li><a href="/seiten/seite-erstellen">Seite erstellen und bearbeiten</a></li></ul>',30)])])}const g=t(r,[["render",s]]);export{b as __pageData,g as default};
